static final int DUEL_SPACE_LEVEL = 0;
static final String DIAGNOSTIC_VERSION = "3.10";
static final String DIAGNOSTIC_BATTLE = Long.toHexString(new java.util.Random().nextLong());
static final boolean EXPORT_LEARNING = false;

private final Telemetry telemetry = new Telemetry();
private long edgeTicks, duelTicks, gunReadyTicks, unavailableAimTicks, duelSpaceQueries;
private double firingDistanceSum;
private int initialOpponents;

if (!roundReported) {
    telemetry.decision(target != null);
    if (wallDistance(getX(), getY()) < 80) edgeTicks++;
    if (getOthers() == 1) duelTicks++;
}

double rangeScale = DUEL_SPACE_LEVEL == 0 ? 1600 : DUEL_SPACE_LEVEL == 1 ? 900 : 650;
risk += Math.abs(d - (USE_FINISHER ? engagementDistance : GENOME[1])) / rangeScale;
if (DUEL_SPACE_LEVEL > 0) {
    double edge = Math.max(0, 1 - wallDistance(x, y) / 100);
    risk += (DUEL_SPACE_LEVEL == 1 ? 0.35 : 0.8) * edge * edge;
    duelSpaceQueries++;
}

if (!roundReported && getGunHeat() == 0) gunReadyTicks++;
if (target == null || getTime() - target.time > 8) {
    if (!roundReported) unavailableAimTicks++;
    return;
}

private void saveDiagnostic() {
    String header = "version,battle,round,rounds,initial_opponents,observed_opponents,ticks,won,energy,decisions,no_target,shots,hits,spent,damage_nominal,received_nominal,waves,matched,walls,skipped,gun_ready_ticks,unavailable_aim_ticks,mean_shot_distance,edge_ticks,duel_ticks,duel_space_queries\n";
    java.util.TreeSet<String> names = new java.util.TreeSet<String>(enemies.keySet());
    StringBuilder opponents = new StringBuilder();
    for (String name : names) {
        if (opponents.length() > 0) opponents.append('|');
        opponents.append(name.replace("\"", "\"\""));
    }
    String row = DIAGNOSTIC_VERSION + "," + DIAGNOSTIC_BATTLE + "," + (getRoundNum() + 1)
            + "," + getNumRounds() + "," + initialOpponents + ",\"" + opponents + "\","
            + getTime() + "," + (celebrating ? 1 : 0) + "," + getEnergy()
            + "," + telemetry.decisions + "," + telemetry.noTarget + "," + shots + "," + hits
            + "," + telemetry.spent + "," + telemetry.dealtNominal + "," + telemetry.receivedNominal
            + "," + wavesDetected + "," + wavesMatched + "," + wallHits + "," + skipped
            + "," + gunReadyTicks + "," + unavailableAimTicks
            + "," + (shots == 0 ? 0 : firingDistanceSum / shots)
            + "," + edgeTicks + "," + duelTicks + "," + duelSpaceQueries + "\n";
    try {
        java.io.File file = getDataFile("diagnostico.csv");
        String old = "";
        if (file.exists() && file.length() <= 48000) {
            java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
            try (java.io.InputStream input = new java.io.FileInputStream(file)) {
                byte[] bytes = new byte[2048]; int count;
                while ((count = input.read(bytes)) != -1) buffer.write(bytes, 0, count);
            }
            String text = new String(buffer.toByteArray(), java.nio.charset.StandardCharsets.UTF_8);
            if (text.startsWith(header)) old = text.substring(header.length());
        }
        String rowKey = DIAGNOSTIC_VERSION + "," + DIAGNOSTIC_BATTLE + "," + (getRoundNum() + 1) + ",";
        StringBuilder kept = new StringBuilder();
        for (String entry : old.split("\\n"))
            if (!entry.isEmpty() && !entry.startsWith(rowKey)) kept.append(entry).append('\n');
        old = kept.toString();
        long budget = Math.min(48000L, file.length() + getDataQuotaAvailable());
        byte[] bytes = (header + old + row).getBytes(java.nio.charset.StandardCharsets.UTF_8);
        while (bytes.length > budget && !old.isEmpty()) {
            int newline = old.indexOf('\n');
            old = newline < 0 ? "" : old.substring(newline + 1);
            bytes = (header + old + row).getBytes(java.nio.charset.StandardCharsets.UTF_8);
        }
        if (bytes.length > budget) throw new java.io.IOException("sem cota para diagnostico");
        try (java.io.OutputStream output = new RobocodeFileOutputStream(file)) { output.write(bytes); }
    } catch (java.io.IOException e) {
        out.println("DIAGNOSTIC_ERROR " + e.getMessage());
    } catch (SecurityException e) {
        out.println("DIAGNOSTIC_ERROR acesso ao arquivo: " + e.getMessage());
    }
}

